    if (argv.isEmpty || argv.length > 64) return false;
    var total = 0;
    for (final arg in argv) {
      total += arg.length;
      if (total > _resumeArgvMaxBytes) return false;
    }
    final head = argv.first;
    if (head.isEmpty || head.contains('/') || head.contains(r'\')) return false;
