    if (name == null) {
      final repo = _repo;
      if (repo is JsonlSessionRepo) {
        try {
          name = await repo.sessionNameQuick(metadata);
        } on Object {
          name = null; // unreadable file at exit: degrade to the id
        }
      }
    }
    final id = name ?? metadata.id;
    return "resume this session with: fa --session '$id'";
  }

